"""Real tiny outer CE/BP + terminal BP/LDPC; not frozen N1024/checkpoint validation."""
import tempfile
import unittest
from unittest.mock import patch
import numpy as np
import torch
from .classical_joint_unrolled import ClassicalJointConfig,ClassicalJointUnrolled
from .direction_receiver import terminal_decode
from .e1_ldpc import build_code
from .supplement_feedback import detector_marginals,ce_expected_residual


class TinyOriginalChain:
    """Test-only orchestration of actual original algorithms, no fake numerics."""
    def __init__(self,code):
        self.cfg=ClassicalJointConfig(N=16,l_max=2,k_max=1,n_paths=2,n_outer_iter=3,
            pic_iter=3,c1=3/32,c2=.001,device='cpu',mp_mode='bp',early_stop=False)
        self.model=ClassicalJointUnrolled(self.cfg,learnable_heads=(),use_soft_decisions=True)
        self.code=code

    def run(self,observed,*,audit=False):
        tensor=lambda a:torch.tensor(a,dtype=torch.complex128)
        with torch.no_grad():
            outer=self.model(tensor(observed['y']),tensor(observed['pilot']),torch.tensor(observed['sigma2'],dtype=torch.float64),
                tensor(observed['constellation']),enable_support_repair=False,receiver_extension=0,active_support_cap=2)
        H=outer['H_est'].numpy();sigma=float(outer['sigma2_final'])
        output=terminal_decode(observed['y']-H@observed['pilot'],H,sigma,observed['constellation'],self.code,device='cpu',audit=audit)
        return dict(output,H=H,sigma2=sigma,x_soft=outer['x_soft'].numpy(),gains=outer['gains'].numpy(),
            delays=outer['support_delays'].numpy(),dopplers=outer['support_dopplers'].numpy(),capacity_trace=outer['capacity_trace'])


def tiny_equivalence():
    with tempfile.TemporaryDirectory() as directory:
        code=build_code(n=32,d_v=2,d_c=4,seed=91,cache_dir=directory)
        chain=TinyOriginalChain(code);rng=np.random.default_rng(712)
        observed=dict(y=rng.normal(size=16)+1j*rng.normal(size=16),
            pilot=np.ones(16,dtype=complex)/2,sigma2=.2,
            constellation=np.array([.5+.5j,.5-.5j,-.5+.5j,-.5-.5j]))
        original=chain.run(observed,audit=True)
        with patch('afdm_sp_joint_unrolled.supplement_messages.decoder_messages',side_effect=AssertionError('disabled feedback called decoder')):
            adapted=chain.run(observed,audit=True)
        fields=('H','x_soft','gains','delays','dopplers','mu','var','llr','decoded','info_hat','x_hard')
        equal={k:bool(np.array_equal(original[k],adapted[k])) for k in fields}
        equal.update(sigma2=original['sigma2']==adapted['sigma2'],decode_ok=original['decode_ok']==adapted['decode_ok'])
        # CPU pivoted LAPACK can differ by a few ulps on identical inputs.
        # Keep the bitwise report, and assess continuous values at roundoff
        # separately from exact support, hard symbols and decoder decisions.
        continuous=('H','x_soft','gains','mu','var','llr','sigma2')
        relative={k:float(np.linalg.norm(np.asarray(original[k])-np.asarray(adapted[k]))/
            max(1.,np.linalg.norm(np.asarray(original[k])))) for k in continuous}
        tolerance=64*np.finfo(np.float64).eps
        roundoff_pass=all(np.isfinite(v) and v<=tolerance for v in relative.values()) and all(
            v for k,v in equal.items() if k not in continuous)
        return dict(all_equal=all(equal.values()),fields=equal,N=16,outer_iterations=3,outer_BP_iterations=3,terminal_BP_iterations=20,
            code_n=32,code_k=code['k'],real_algorithms=True,frozen_N1024_checkpoint=False,disabled_integrated_hook=False,
            roundoff_pass=roundoff_pass,continuous_relative_errors=relative,roundoff_tolerance=tolerance)


class FeedbackTests(unittest.TestCase):
    def test_real_tiny_original_complete_chain_reproducible(self):
        result=tiny_equivalence();self.assertTrue(result['roundoff_pass'],result)

    def test_tiny_roundoff_check_rejects_material_soft_error(self):
        original=TinyOriginalChain.run;calls=[]
        def shifted(chain,*args,**kwargs):
            value=original(chain,*args,**kwargs);calls.append(1)
            if len(calls)==2:value['gains']=value['gains']+1e-7
            return value
        with patch.object(TinyOriginalChain,'run',new=shifted):
            result=tiny_equivalence()
        self.assertFalse(result['roundoff_pass'])

    def test_prior_consumer_exact_enumeration_and_disabled(self):
        likelihood=np.array([[.2,-.4,.8,-.1],[.4,.1,-.8,.5]])
        prior=np.array([1.2,-.7,.3,2.])
        result=detector_marginals(likelihood,prior,enabled=True)
        const=np.array([.5+.5j,.5-.5j,-.5+.5j,-.5-.5j])
        for i in range(2):
            weights=[]
            for j,symbol in enumerate(const):
                weights.append(np.exp(likelihood[i,j]+.5*(1-2*int(symbol.real<0))*prior[i]+.5*(1-2*int(symbol.imag<0))*prior[2+i]))
            expected=np.array(weights)/sum(weights)
            np.testing.assert_allclose(result['probabilities'][i],expected,atol=1e-14)
        disabled=detector_marginals(likelihood,prior,enabled=False)
        zero=detector_marginals(likelihood,np.zeros(4),enabled=True)
        np.testing.assert_array_equal(disabled['probabilities'],zero['probabilities'])
        independent=np.exp(likelihood-likelihood.max(axis=1,keepdims=True));independent/=independent.sum(axis=1,keepdims=True)
        np.testing.assert_allclose(disabled['probabilities'],independent,atol=1e-14)

    def test_ce_quadratic_matches_exact_factorized_symbol_enumeration(self):
        import itertools
        likelihood=np.array([[.2,-.4,.8,-.1],[.4,.1,-.8,.5]])
        posterior=detector_marginals(likelihood,np.array([1.,-1.,.2,.3]),enabled=True)
        H=np.array([[1,.2j],[.3,1-.1j]]);pilot=np.array([.1,.2j]);y=np.array([.7+.2j,-.3+.4j])
        result=ce_expected_residual(y,pilot,H,posterior)
        const=np.array([.5+.5j,.5-.5j,-.5+.5j,-.5-.5j]);expected=0.
        for a,b in itertools.product(range(4),repeat=2):
            residual=y-H@(pilot+const[[a,b]])
            expected+=posterior['probabilities'][0,a]*posterior['probabilities'][1,b]*np.vdot(residual,residual).real
        self.assertAlmostEqual(result['expected_squared_residual'],expected,places=13)

    def test_consumer_domains(self):
        with self.assertRaises(ValueError):detector_marginals(np.zeros((2,4)),np.zeros(3),enabled=True)
        with self.assertRaises(ValueError):detector_marginals(np.full((2,4),np.nan),np.zeros(4),enabled=True)
        with self.assertRaises(ValueError):ce_expected_residual(np.ones(2),np.ones(2),np.eye(2),{'mu':np.ones(2),'var':-np.ones(2)})


if __name__=='__main__':unittest.main()

